import { names } from '../data';

function Table() {
    return (
        <section id='table'>
            <table id='table'>
                <thead>
                    <tr>
                        <th>Name</th>
                    </tr>
                    <tr>
                        {names.map((name, key) =>
                            <th id={key}>
                                {name}
                            </th>)
                        }
                    </tr>
                </thead>
                <tbody>

                </tbody>
            </table>
        </section>
    );
}

export default Table;
